object a = new(), b = new();
var t1 = new Thread(() => {
  lock (a) {
    Thread.Sleep(100);
    lock (b) { /* ... */ }
  } });
var t2 = new Thread(() => {
  lock (b) {
    Thread.Sleep(100);
    lock (a) { /* ... */ }
  } });
t1.Start(); t2.Start();
// t1 hält a, wartet auf b
// t2 hält b, wartet auf a
// → Programm hängt für immer

void Arbeite(string name,
    object erste, object zweite)
{
  lock (erste)
  {
    Thread.Sleep(100);
    if (Monitor.TryEnter(zweite,
          TimeSpan.FromSeconds(1)))
    {
      try { Console.WriteLine(
              $"{name}: fertig"); }
      finally {
        Monitor.Exit(zweite); }
    }
    else
      Console.WriteLine(
        $"{name}: Deadlock!");
  }
}
// T1: Arbeite("T1", a, b)
// T2: Arbeite("T2", b, a)

static void Ueberweise(
    Konto von, Konto nach, decimal b)
{
    var (x, y) = von.Id < nach.Id
        ? (von, nach) : (nach, von);
    lock (x.Sperre)
    lock (y.Sperre)
    {
        von.Stand -= b;
        nach.Stand += b;
    }
}
